	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// mirrorMetadataToV1CustomRefStrict is the package-level seam tests swap. It
// matches the real implementation's signature and lets unit tests inject a
// failure path without having to engineer a real ref divergence.
var mirrorMetadataToV1CustomRefStrict = mirrorMetadataToV1CustomRefStrictReal

// mirrorMetadataToV1CustomRefStrictReal advances the v1 custom ref
// (refs/entire/checkpoints/v1.1) to the v1 metadata branch's current commit
// when checkpoints_version "1.1" is opted in, returning errors instead of
// logging them.
//
// User-facing commands (`session attach`, `checkpoint explain --generate`)
// run this strict variant after a successful v1 committed write so a mirror
// failure surfaces to the user rather than being silently dropped. Hook-side
// writes use the log-only strategy.mirrorMetadataToV1CustomRef instead.
//
// v1 remains the source of truth; the v1 custom ref is a local-only mirror
// sharing v1's exact commit — nothing reads it and it is never pushed.
func mirrorMetadataToV1CustomRefStrictReal(ctx context.Context, repo *git.Repository) error {
	if !settings.MirrorsToV1CustomRef(ctx) {
		return nil
	}

	v1Ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return fmt.Errorf("v1 metadata branch %s is missing after a v1 write", paths.MetadataBranchName)
		}
		return fmt.Errorf("read v1 metadata branch %s: %w", paths.MetadataBranchName, err)
	}

	v1CustomRef := plumbing.ReferenceName(paths.MetadataRefName)
	if err := strategy.SafelyAdvanceLocalRef(ctx, repo, v1CustomRef, v1Ref.Hash()); err != nil {
		return fmt.Errorf("advance v1 custom ref %s: %w", paths.MetadataRefName, err)
	}
	return nil
}

